package com.abluepoint.summer.sample.application;

import com.abluepoint.summer.common.response.ApiError;
import com.abluepoint.summer.common.response.ApiResponse;
import com.abluepoint.summer.mvc.api.RawResponse;
import com.abluepoint.summer.mvc.request.RequestIdAccessor;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.http.*;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;
import java.util.List;

@RestController
@PreAuthorize("isAuthenticated()")
class ApplicationController {
 private final ApplicationService service; private final RequestIdAccessor requestId;
 ApplicationController(ApplicationService s,RequestIdAccessor r){service=s;requestId=r;}
 @GetMapping("/api/v1/enterprises/{enterpriseId}/applications") @PreAuthorize("hasAnyAuthority('SCOPE_enterprise.application.read','SCOPE_enterprise.applications.read')") @RawResponse ResponseEntity<ApiResponse<List<ApplicationView>>> list(@PathVariable String enterpriseId,Authentication a){return ok(service.list(enterpriseId,a),null);}
 @PostMapping(value="/api/v1/enterprises/{enterpriseId}/applications",consumes=MediaType.APPLICATION_JSON_VALUE) @RawResponse ResponseEntity<ApiResponse<ApplicationView>> create(@PathVariable String enterpriseId,@RequestBody ApplicationCreateRequest b,@RequestHeader(value="Idempotency-Key",required=false)String k,Authentication a){try{ApplicationView v=service.create(enterpriseId,b,k,rid(),a);return out(HttpStatus.CREATED,v,v.version());}catch(Exception e){return err(e);}}
 @GetMapping("/api/v1/enterprises/{enterpriseId}/applications/{id}") @RawResponse ResponseEntity<ApiResponse<ApplicationView>> detail(@PathVariable String enterpriseId,@PathVariable String id,Authentication a){try{return out(HttpStatus.OK,service.detail(enterpriseId,id,a),service.detail(enterpriseId,id,a).version());}catch(Exception e){return err(e);}}
 @PatchMapping(value="/api/v1/enterprises/{enterpriseId}/applications/{id}",consumes=MediaType.APPLICATION_JSON_VALUE) @RawResponse ResponseEntity<ApiResponse<ApplicationView>> update(@PathVariable String enterpriseId,@PathVariable String id,@RequestBody ApplicationUpdateRequest b,@RequestHeader("If-Match")String ifm,@RequestHeader(value="Idempotency-Key",required=false)String k,Authentication a){try{ApplicationView v=service.update(enterpriseId,id,b,ifm,k,rid(),a);return out(HttpStatus.OK,v,v.version());}catch(Exception e){return err(e);}}
 @PostMapping("/api/v1/enterprises/{enterpriseId}/applications/{id}:enable") @RawResponse ResponseEntity<ApiResponse<ApplicationView>> enable(@PathVariable String enterpriseId,@PathVariable String id,@RequestHeader("If-Match")String ifm,@RequestHeader(value="Idempotency-Key",required=false)String k,Authentication a){return status(enterpriseId,id,"ACTIVE",ifm,k,a);}
 @PostMapping("/api/v1/enterprises/{enterpriseId}/applications/{id}:disable") @RawResponse ResponseEntity<ApiResponse<ApplicationView>> disable(@PathVariable String enterpriseId,@PathVariable String id,@RequestHeader("If-Match")String ifm,@RequestHeader(value="Idempotency-Key",required=false)String k,Authentication a){return status(enterpriseId,id,"DISABLED",ifm,k,a);}
 private ResponseEntity<ApiResponse<ApplicationView>> status(String e,String id,String st,String ifm,String k,Authentication a){try{ApplicationView v=service.setStatus(e,id,st,ifm,k,rid(),a);return out(HttpStatus.OK,v,v.version());}catch(Exception x){return err(x);}}
 @GetMapping("/api/v1/enterprises/{enterpriseId}/applications/{id}/oauth-config") @RawResponse ResponseEntity<ApiResponse<OAuthConfigView>> oauth(@PathVariable String enterpriseId,@PathVariable String id,Authentication a){try{ApplicationView v=service.detail(enterpriseId,id,a);return out(HttpStatus.OK,v.oauthConfig(),v.oauthConfig().version());}catch(Exception e){return err(e);}}
 @PutMapping(value="/api/v1/enterprises/{enterpriseId}/applications/{id}/oauth-config",consumes=MediaType.APPLICATION_JSON_VALUE) @RawResponse ResponseEntity<ApiResponse<OAuthConfigView>> config(@PathVariable String enterpriseId,@PathVariable String id,@RequestBody OAuthConfigRequest b,@RequestHeader("If-Match")String ifm,@RequestHeader(value="Idempotency-Key",required=false)String k,Authentication a){try{ApplicationView v=service.configure(enterpriseId,id,b,ifm,k,rid(),a);return out(HttpStatus.OK,v.oauthConfig(),v.version());}catch(Exception e){return err(e);}}
 @GetMapping("/api/v1/enterprises/{enterpriseId}/applications/{id}/credentials") @RawResponse ResponseEntity<ApiResponse<List<CredentialView>>> credentials(@PathVariable String enterpriseId,@PathVariable String id,Authentication a){try{return ok(service.credentials(enterpriseId,id,a),null);}catch(Exception e){return err(e);}}
 @PostMapping("/api/v1/enterprises/{enterpriseId}/applications/{id}/credentials:rotate") @RawResponse ResponseEntity<ApiResponse<CredentialView>> rotate(@PathVariable String enterpriseId,@PathVariable String id,@RequestHeader("If-Match")String ifm,@RequestHeader(value="Idempotency-Key",required=false)String k,Authentication a){try{CredentialView v=service.rotate(enterpriseId,id,ifm,k,rid(),a);return out(HttpStatus.OK,v,(long)v.version());}catch(Exception e){return err(e);}}
 @PostMapping("/api/v1/enterprises/{enterpriseId}/applications/{id}/credentials/{cid}:revoke") @RawResponse ResponseEntity<ApiResponse<CredentialView>> revoke(@PathVariable String enterpriseId,@PathVariable String id,@PathVariable String cid,@RequestHeader("If-Match")String ifm,@RequestHeader(value="Idempotency-Key",required=false)String k,Authentication a){try{return out(HttpStatus.OK,service.revoke(enterpriseId,id,cid,ifm,k,rid(),a),null);}catch(Exception e){return err(e);}}
 @GetMapping("/api/v1/enterprises/{enterpriseId}/applications/{id}/audit") @RawResponse ResponseEntity<ApiResponse<List<java.util.Map<String,Object>>>> audit(@PathVariable String enterpriseId,@PathVariable String id,Authentication a){try{return ok(service.audit(enterpriseId,id,a),null);}catch(Exception e){return err(e);}}
 private String rid(){return requestId.currentRequestId();}
 private <T> ResponseEntity<ApiResponse<T>> ok(T b,Long v){return out(HttpStatus.OK,b,v);}
 private <T> ResponseEntity<ApiResponse<T>> out(HttpStatus s,T b,Long ver){ResponseEntity.BodyBuilder rb=ResponseEntity.status(s).header("X-Request-Id",rid());if(ver!=null)rb.eTag("\""+ver+"\"");return rb.body(ApiResponse.success(b,rid()));}
 private <T> ResponseEntity<ApiResponse<T>> err(Exception e){HttpStatus s=HttpStatus.INTERNAL_SERVER_ERROR;String c="SUMMER_INTERNAL_ERROR";if(e instanceof org.springframework.security.access.AccessDeniedException){s=HttpStatus.FORBIDDEN;c="SUMMER_FORBIDDEN";}else if(e instanceof ApplicationValidationException){s=HttpStatus.BAD_REQUEST;c="SUMMER_APPLICATION_INVALID";}else if(e instanceof ApplicationPreconditionException){s=HttpStatus.PRECONDITION_FAILED;c="SUMMER_PRECONDITION_FAILED";}else if(e instanceof ApplicationIdempotencyConflictException||e instanceof ApplicationConflictException){s=HttpStatus.CONFLICT;c=e instanceof ApplicationIdempotencyConflictException?"SUMMER_IDEMPOTENCY_CONFLICT":"SUMMER_APPLICATION_CONFLICT";}return ResponseEntity.status(s).header("X-Request-Id",rid()).body(ApiResponse.failure(new ApiError(c,e.getMessage(),List.of()),rid()));}
}
